222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
